function illustration(label: string, background: string, accent: string) {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 520"><rect width="800" height="520" fill="${background}"/><circle cx="650" cy="90" r="150" fill="${accent}" opacity=".22"/><ellipse cx="400" cy="315" rx="245" ry="70" fill="#f5e6ca"/><path d="M170 300c24 120 107 164 230 164s206-44 230-164" fill="#fff8ea"/><ellipse cx="400" cy="295" rx="230" ry="73" fill="#8b563c"/><ellipse cx="400" cy="280" rx="210" ry="62" fill="#a66b44"/><g fill="${accent}" opacity=".75"><circle cx="280" cy="275" r="18"/><circle cx="340" cy="300" r="15"/><circle cx="420" cy="267" r="17"/><circle cx="490" cy="300" r="16"/></g><text x="400" y="95" text-anchor="middle" font-family="Arial,sans-serif" font-size="44" font-weight="700" fill="#fff8ea">${label}</text></svg>`;
  return `data:image/svg+xml,${encodeURIComponent(svg)}`;
}

type IngredientInput = Omit<RecipeIngredientRecord, "unitArabic" | "substitutions"> & {
  substitutions?: RecipeIngredientRecord["substitutions"];
};
type StepInput = RecipeStepRecord;
type RecipeInput = Omit<InsertRecipe, "imageUrl" | "ingredients" | "steps"> & {
  imageLabel: string;
  imageBackground: string;
  imageAccent: string;
  ingredients: IngredientInput[];
  steps: StepInput[];
};

function recipe(input: RecipeInput): InsertRecipe {
  return {
    ...input,
    imageUrl: illustration(input.imageLabel, input.imageBackground, input.imageAccent),
    ingredients: input.ingredients.map((item) => ({
      ...item,
      unitArabic: arabicUnits[item.unit] ?? item.unit,
      substitutions: item.substitutions ?? recipeSubstitutions[input.recipeId]?.[item.ingredientId] ?? [],
    })),
  };
}

const noSwap = (ingredient: string, ingredientArabic: string) => [{
  ingredient,
  ingredientArabic,
  quantity: 0,
  unit: "none",
  unitArabic: "لا يوجد",
  effect: "No suitable substitution is recommended because it changes the dish's defining texture or flavor.",
  effectArabic: "لا يُنصح ببديل مناسب لأن تغييره يبدل القوام أو الطعم الأساسي للطبق.",
}];

const substitution = (ingredient: string, ingredientArabic: string, quantity: number, unit: string, effect: string, effectArabic: string): RecipeIngredientRecord["substitutions"] => [{
  ingredient, ingredientArabic, quantity, unit, unitArabic: arabicUnits[unit] ?? unit, effect, effectArabic,
}];

