function assertRecipeQuality(recipes: InsertRecipe[]) {
  const recipeIds = new Set<string>();

  for (const recipe of recipes) {
    if (recipeIds.has(recipe.recipeId)) throw new Error(`Duplicate recipe ID: ${recipe.recipeId}`);
    recipeIds.add(recipe.recipeId);

    const requiredText = [recipe.recipeId, recipe.name, recipe.nameArabic, recipe.description, recipe.descriptionArabic, recipe.cuisine, recipe.category, recipe.mealType, recipe.difficulty];
    if (requiredText.some((value) => !value?.trim())) throw new Error(`Incomplete metadata: ${recipe.recipeId}`);
    if (!recipe.imageUrl?.trim() || !recipe.tags?.length) throw new Error(`Missing image or tags: ${recipe.recipeId}`);
    if (recipe.totalTimeMinutes !== recipe.prepTimeMinutes + recipe.cookTimeMinutes) throw new Error(`Invalid timing: ${recipe.recipeId}`);
    if (recipe.ingredients.length === 0 || recipe.steps.length === 0) throw new Error(`Missing ingredients or steps: ${recipe.recipeId}`);
    if (!recipe.ingredients.some((item) => item.substitutions.length > 0)) throw new Error(`Missing substitution guidance: ${recipe.recipeId}`);

    for (const item of recipe.ingredients) {
      if (!item.ingredientId || !item.name.trim() || !item.nameArabic?.trim() || item.quantity <= 0 || !item.unit.trim() || !item.group.trim()) {
        throw new Error(`Incomplete ingredient: ${recipe.recipeId}/${item.ingredientId}`);
      }
    }

    for (const step of recipe.steps) {
      if (!step.title.trim() || !step.titleArabic?.trim() || !step.instruction.trim() || !step.instructionArabic?.trim() || !step.cookingCue.trim() || !step.cookingCueArabic?.trim() || !step.heatLevel?.trim() || !step.heatLevelArabic?.trim()) {
        throw new Error(`Incomplete cooking step: ${recipe.recipeId}/${step.stepNumber}`);
      }
    }
  }
}

